import postsJson from './medium-posts.json';

// Generated by `npm run sync:medium` — edit the overrides below, not the JSON.
export type MediumPost = {
  id: string;
  slug: string;
  title: string;
  url: string;
  publication: { name: string; url: string } | null;
  publishedAt: string;
  updatedAt: string;
  tags: string[];
  cover: string | null;
  excerpt: string;
  readingMinutes: number;
  headings: { id: string; label: string; depth: number }[];
  html: string;
};

// Medium has no public API for claps, so these are a snapshot from Medium,
// keyed by post slug. Posts without a count just don't show one.
const overrides: Record<string, { claps?: number; hidden?: boolean }> = {
  'disclaimer': { hidden: true },
  'zoom-out-from-google-maps-to-remote-sensing-at-mit-bwsi': { claps: undefined },
  'we-scrapped-our-tsa-podcast-at-midnight-and-still-placed-3rd': { claps: undefined },
  'part-ii-when-awareness-isnt-enough': { claps: undefined },
  'what-access-looks-like-for-the-malto': { claps: undefined },
  'city-lights-and-shadows-bias-crime-and-life-in-the-gilded-age': { claps: undefined },
  'the-complete-guide-to-spatial-data-unlocking-the-power-of-location-intelligence': { claps: undefined },
  'engineer-your-world-safer-buildings-unit-assignment': { claps: undefined },
  'launching-dreams-my-rocketry-journey': { claps: undefined },
  'engineer-you-world-pinhole-camera-technical-report': { claps: undefined },
};

export type Article = MediumPost & { claps?: number };

export const articles: Article[] = (postsJson as MediumPost[])
  .filter((p) => !overrides[p.slug]?.hidden)
  .map((p) => ({ ...p, claps: overrides[p.slug]?.claps }));

export function getArticle(slug: string) {
  return articles.find((a) => a.slug === slug);
}

export function formatDate(iso: string) {
  return new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' });
}

export function formatClaps(n: number) {
  return n >= 1000 ? `${(n / 1000).toFixed(n >= 10000 ? 0 : 1).replace(/\.0$/, '')}K` : String(n);
}
